@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products..."
           @oninput="OnSearchInput"
           class="product-search-input" />

    @if (_isLoading)
    {
        <div class="product-search-status">Searching...</div>
    }
    else if (_error is not null)
    {
        <div class="product-search-error">
            <p>Something went wrong: @_error</p>
            <button @onclick="RetrySearch">Retry</button>
        </div>
    }
    else if (_hasSearched && _results is { Count: 0 })
    {
        <div class="product-search-status">No products found.</div>
    }
    else if (_results is { Count: > 0 })
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" class="product-card-image" />
                    <div class="product-card-body">
                        <h4 class="product-card-name">@product.Name</h4>
                        <p class="product-card-price">@product.Price.ToString("C")</p>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<Product>? _results;
    private bool _isLoading;
    private bool _hasSearched;
    private string? _error;
    private string _currentQuery = string.Empty;

    private Timer? _debounceTimer;
    private CancellationTokenSource? _searchCts;

    private void OnSearchInput(ChangeEventArgs e)
    {
        _currentQuery = e.Value?.ToString() ?? string.Empty;

        _debounceTimer?.Dispose();
        _debounceTimer = new Timer(OnDebounceElapsed, null, 300, Timeout.Infinite);
    }

    private async void OnDebounceElapsed(object? state)
    {
        await InvokeAsync(ExecuteSearch);
    }

    private async Task ExecuteSearch()
    {
        var query = _currentQuery;

        if (string.IsNullOrWhiteSpace(query))
        {
            _results = null;
            _hasSearched = false;
            _error = null;
            _isLoading = false;
            StateHasChanged();
            return;
        }

        // Cancel any in-flight search
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = new CancellationTokenSource();
        var ct = _searchCts.Token;

        _isLoading = true;
        _error = null;
        StateHasChanged();

        try
        {
            var results = await ProductService.SearchAsync(query, ct);

            if (ct.IsCancellationRequested)
                return;

            _results = results;
            _hasSearched = true;
            _error = null;
        }
        catch (OperationCanceledException)
        {
            // Search was superseded by a newer query; do nothing.
            return;
        }
        catch (Exception ex)
        {
            if (ct.IsCancellationRequested)
                return;

            _error = ex.Message;
            _results = null;
        }
        finally
        {
            if (!ct.IsCancellationRequested)
            {
                _isLoading = false;
                StateHasChanged();
            }
        }
    }

    private async Task RetrySearch()
    {
        await ExecuteSearch();
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    public void Dispose()
    {
        _debounceTimer?.Dispose();
        _searchCts?.Cancel();
        _searchCts?.Dispose();
    }
}

