+    private async Task OnSearchInput(ChangeEventArgs e)
+    {
+        _query = e.Value?.ToString() ?? string.Empty;
+
+        // Cancel any pending debounce timer
+        _debounceCts?.Cancel();
+        _debounceCts?.Dispose();
+        _debounceCts = new CancellationTokenSource();
+
+        var debounceToken = _debounceCts.Token;
+
+        try
+        {
+            await Task.Delay(300, debounceToken);
+        }
+        catch (TaskCanceledException)
+        {
+            return;
+        }
+
+        await ExecuteSearch();
+    }
+
+    private async Task ExecuteSearch()
+    {
+        var query = _query.Trim();
+
+        if (string.IsNullOrEmpty(query))
+        {
+            _results = new();
+            _hasSearched = false;
+            _error = null;
+            return;
+        }
+
+        // Cancel any in-flight search
+        _searchCts?.Cancel();
+        _searchCts?.Dispose();
+        _searchCts = new CancellationTokenSource();
+
+        var searchToken = _searchCts.Token;
+
+        _isLoading = true;
+        _error = null;
+
+        try
+        {
+            _results = await ProductService.SearchAsync(query, searchToken);
+            _hasSearched = true;
+        }
+        catch (TaskCanceledException)
+        {
+            // Search was superseded by a newer one; do nothing
+            return;
+        }
+        catch (Exception ex)
+        {
+            _results = new();
+            _error = ex.Message;
+        }
+        finally
+        {
+            if (!searchToken.IsCancellationRequested)
+            {
+                _isLoading = false;
+            }
+        }
+    }
+
+    private async Task RetrySearch()
+    {
+        await ExecuteSearch();
+    }
+
+    private async Task SelectProduct(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    public void Dispose()
+    {
+        _debounceCts?.Cancel();
+        _debounceCts?.Dispose();
+        _searchCts?.Cancel();
+        _searchCts?.Dispose();
+    }
